solutions.naive:
class Solution:
    def maxScore(self, nums1, nums2, k):
        from itertools import combinations
        n = len(nums1)
        best = 0
        for combo in combinations(range(n), k):
            total = 0
            minimum = None
            for idx in combo:
                total += nums1[idx]
                if minimum is None or nums2[idx] < minimum:
                    minimum = nums2[idx]
            best = max(best, total * minimum)
        return best

solutions.better:
class Solution:
    def maxScore(self, nums1, nums2, k):
        n = len(nums1)
        best = 0
        for i in range(n):
            threshold = nums2[i]
            candidates = []
            for j in range(n):
                if nums2[j] >= threshold:
                    candidates.append(nums1[j])
            if len(candidates) >= k:
                candidates.sort(reverse=True)
                best = max(best, sum(candidates[:k]) * threshold)
        return best

solutions.optimal:
class Solution:
    def maxScore(self, nums1, nums2, k):
        import heapq
        pairs = sorted(zip(nums2, nums1), reverse=True)
        heap = []
        total = 0
        best = 0
        for value2, value1 in pairs:
            heapq.heappush(heap, value1)
            total += value1
            if len(heap) > k:
                total -= heapq.heappop(heap)
            if len(heap) == k:
                best = max(best, total * value2)
        return best

